def encrypt(s):
    encrypted = ""
    for char in s:
        if char.isalpha():
            if char.islower():
                encrypted += chr((ord(char) - ord('a') + 3) % 26 + ord('a'))
            else:
                encrypted += chr((ord(char) - ord('A') + 3) % 26 + ord('A'))
        else:
            encrypted += char
    return encrypted
```

